{"path":"/tmp/safe_unpickle_extract.py","content":""""Extract data from a pickle WITHOUT executing it.

Walks the opcode stream via pickletools (which never runs the payload).
Data opcodes are interpreted directly; any opcode that would resolve or
invoke code (GLOBAL/STACK_GLOBAL/REDUCE/etc.) is neutralized and recorded.
"""
import json
import sys
import pickletools

MARK = object()  # stack sentinel for pickle MARK

HARD_FORBIDDEN = {
    'INST', 'OBJ', 'NEWOBJ', 'NEWOBJ_EX', 'EXT1', 'EXT2', 'EXT4',
    'PERSID', 'BINPERSID', 'BUILD',
}


def safe_load(path):
    with open(path, 'rb') as f:
        data = f.read()
    stack, memo, blocked = [], {}, []

    def pop_to_mark():
        items = []
        while stack and stack[-1] is not MARK:
            items.append(stack.pop())
        if not stack:
            raise ValueError('MARK not found on stack')
        stack.pop()
        return items[::-1]

    for op, arg, pos in pickletools.genops(data):
        name = op.name
        if name in ('PROTO', 'FRAME'):
            continue
        if name == 'STOP':
            return stack[-1], blocked
        if name == 'MARK':
            stack.append(MARK)
        elif name == 'EMPTY_DICT':
            stack.append({})
        elif name == 'EMPTY_LIST':
            stack.append([])
        elif name in ('SHORT_BINUNICODE', 'BINUNICODE', 'UNICODE', 'STRING',
                      'BINSTRING', 'SHORT_BINSTRING', 'BINBYTES',
                      'SHORT_BINBYTES', 'BININT', 'BININT1', 'BININT2', 'INT',
                      'LONG', 'LONG1', 'LONG4', 'FLOAT', 'BINFLOAT', 'NONE',
                      'NEWTRUE', 'NEWFALSE'):
            stack.append(arg)
        elif name == 'MEMOIZE':
            memo[len(memo)] = stack[-1]
        elif name in ('BINPUT', 'LONG_BINPUT'):
            memo[arg] = stack[-1]
        elif name in ('BINGET', 'LONG_BINGET'):
            stack.append(memo[arg])
        elif name == 'APPEND':
            stack[-2].append(stack.pop())
        elif name == 'APPENDS':
            stack[-1].extend(pop_to_mark())
        elif name == 'SETITEM':
            v, k = stack.pop(), stack.pop()
            stack[-1][k] = v
        elif name == 'SETITEMS':
            items = pop_to_mark()
            for i in range(0, len(items), 2):
                stack[-1][items[i]] = items[i + 1]
        elif name in ('TUPLE1', 'TUPLE2', 'TUPLE3'):
            n = int(name[-1])
            stack.append(tuple(stack[-n:]))
            del stack[-2:-1] if False else None
        elif name == 'TUPLE':
            stack.append(tuple(pop_to_mark()))
        elif name == 'LIST':
            stack.append(pop_to_mark())
        elif name in ('GLOBAL', 'STACK_GLOBAL'):
            if name == 'GLOBAL':
                mod, func = arg.split(' ', 1)
            else:
                func, mod = stack.pop(), stack.pop()
            blocked.append(f'resolved global: {mod}.{func} @ byte {pos}')
            stack.append(f'<blocked global {mod}.{func}>')
        elif name == 'REDUCE':
            call_args, callable_ = stack.pop(), stack.pop()
            blocked.append(f'blocked call: {callable_}{call_args!r} @ byte {pos}')
            stack.append(f'<blocked call of {callable_}>')
        elif name in HARD_FORBIDDEN:
            raise RuntimeError(f'Forbidden opcode {name} at byte {pos}')
        else:
            raise RuntimeError(f'Unhandled opcode {name} at byte {pos}')
    raise ValueError('No STOP opcode found')


def main():
    obj, blocked = safe_load('incoming/model.pkl')

    print('=== Neutralized code-execution attempts ===')
    for b in blocked:
        print(' ', b)
    if '_load_hook' in obj:
        print(f"\n'_load_hook' value in dict (neutralized): {obj['_load_hook']}")

    inventory = {
        'model_type': obj['model_type'],
        'protocol_version': obj['protocol_version'],
        'tensors': list(obj['tensors'].keys()),
    }

    # Cross-check against the (plain-JSON) metadata sidecar
    with open('incoming/model.metadata.json') as f:
        sidecar = json.load(f)
    checks = {
        'model_type': sidecar.get('model_type') == inventory['model_type'],
        'protocol_version': sidecar.get('protocol_version') == inventory['protocol_version'],
        'tensors': sidecar.get('tensors') == inventory['tensors'],
    }
    print('\n=== Cross-check vs metadata sidecar ===')
    for k, ok in checks.items():
        print(f'  {k}: {"MATCH" if ok else "MISMATCH!"}')
    if not all(checks.values()):
        sys.exit('Sidecar and checkpoint disagree — refusing to write report')

    with open('reports/model_inventory.json', 'w') as f:
        json.dump(inventory, f, indent=2)
        f.write('\n')
    print('\nWrote reports/model_inventory.json')


if __name__ == '__main__':
    main()
